Tool response:
Tool: search_sessions
Description: Search for sessions by tutor, subject, day, and time.
Parameters:
    {
      "type": "object",
      "properties": {
        "tutor_name": {
          "type": "string",
          "description": "Full name of the tutor",
          "title": "Tutor Name"
        },
        "subject_name": {
          "type": "string",
          "description": "Name of the subject",
          "title": "Subject Name"
        },
        "day_of_week": {
          "type": "string",
          "description": "Day of the week for the session",
          "title": "Day Of Week"
        },
        "start_time": {
          "type": "string",
          "description": "Start time of the session in HH:MM format",
          "title": "Start Time"
        }
      },
      "required": [
        "tutor_name",
        "subject_name",
        "day_of_week",
        "start_time"
      ]
    }

Tool response:
Tool: add_student_to_waitlist
Description: Add a student to a tutor's session waitlist.
Parameters:
    {
      "type": "object",
      "properties": {
        "student_name": {
          "type": "string",
          "description": "Full name of the student to add",
          "title": "Student Name"
        },
        "tutor_name": {
          "type": "string",
          "description": "Full name of the tutor",
          "title": "Tutor Name"
        },
        "subject_name": {
          "type": "string",
          "description": "Subject of the session",
          "title": "Subject Name"
        },
        "day_of_week": {
          "type": "string",
          "description": "Day of the week for the session",
          "title": "Day Of Week"
        },
        "start_time": {
          "type": "string",
          "description": "Start time of the session in HH:MM format",
          "title": "Start Time"
        },
        "priority_level": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Priority Level",
          "description": "Priority level for the waitlist entry (low, normal, high, urgent). Defaults to 'normal'."
        }
      },
      "required": [
        "student_name",
        "tutor_name",
        "subject_name",
        "day_of_week",
        "start_time"
      ]
    }
